results.before:
string(key: string, fallback: string): string {
  const r = this.#read(key);
  if (!r.valid) return '';
  const v = r.value ?? fallback;
  this.#record(key, v, r.value !== undefined);
  return v;
}

results.after:
string(key: string, fallback: string): string {
  const r = this.#read(key);
  if (!r.valid) return '';
  const v = r.value || fallback;
  this.#record(key, v, r.value !== undefined);
  return v;
}
